### Test Spring Data JPA Repositories with In-Memory Database

Source: https://github.com/spring-projects/spring-boot/blob/v2.7.18/spring-boot-project/spring-boot-docs/src/docs/asciidoc/features/testing.adoc

Demonstrates how to use `@DataJpaTest` for testing Spring Data JPA repositories. By default, this annotation configures an in-memory embedded database, making tests fast and self-contained. It's suitable for unit and integration tests that do not require a persistent database.

```Java
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;
import org.springframework.beans.factory.annotation.Autowired;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

@DataJpaTest
class MyRepositoryTests {

    @Autowired
    private TestEntityManager entityManager;

    @Autowired
    private MyRepository myRepository; // Assuming MyRepository is a Spring Data JPA repository

    @Test
    void testExampleEntityPersistence() {
        // Example: Persist an entity and find it
        MyEntity entity = new MyEntity("testName");
        entityManager.persist(entity);
        entityManager.flush();

        MyEntity found = myRepository.findByName("testName");
        assertThat(found).isNotNull();
        assertThat(found.getName()).isEqualTo("testName");
    }
}
// Assuming MyEntity and MyRepository exist
class MyEntity {
    private Long id;
    private String name;
    public MyEntity(String name) { this.name = name; }
    public Long getId() { return id; }
    public String getName() { return name; }
    public void setId(Long id) { this.id = id; }
    public void setName(String name) { this.name = name; }
}
interface MyRepository {
    MyEntity findByName(String name);
}
```

