### Test Spring Data JPA Repositories Against a Real Database

Source: https://github.com/spring-projects/spring-boot/blob/v2.7.18/spring-boot-project/spring-boot-docs/src/docs/asciidoc/features/testing.adoc

Illustrates how to configure `@DataJpaTest` to run against a real, external database instead of the default in-memory embedded database. This is achieved by using the `@AutoConfigureTestDatabase(replace = Replace.NONE)` annotation, which prevents Spring Boot from replacing the configured DataSource. This setup is useful for integration tests that require a specific database environment.

```Java
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase.Replace;
import org.springframework.beans.factory.annotation.Autowired;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

@DataJpaTest
@AutoConfigureTestDatabase(replace = Replace.NONE) // Use the real database
class MyRepositoryTests {

    @Autowired
    private MyRepository myRepository; // Assuming MyRepository is a Spring Data JPA repository

    @Test
    void testExampleEntityRetrieval() {
        // Example: Retrieve an entity from the real database
        // This test assumes data might exist or is set up externally
        MyEntity found = myRepository.findByName("existingName");
        assertThat(found).isNotNull();
        assertThat(found.getName()).isEqualTo("existingName");
    }
}
// Assuming MyEntity and MyRepository exist as defined previously
```

